    for (let i = 0;i < 256; i++) {
      p[i] = i;
    }
    for (let i = 255;i > 0; i--) {
      const r = Math.floor(Math.random() * (i + 1));
      [p[i], p[r]] = [p[r], p[i]];
    }
    for (let i = 0;i < 512; i++) {
      this.perm[i] = p[i & 255];
    }
